//! Terminal session identifiers.

use std::fmt;
use std::str::FromStr;
use std::sync::{Mutex, OnceLock, PoisonError};

use ulid::{Generator, Ulid};

/// A terminal session id: a ULID so ids sort by creation time.
///
/// The id is generated by [`SessionId::new`] unless the caller supplies one in
/// [`SpawnSpec`](crate::SpawnSpec). It is passed to the child as
/// `TESSERA_SESSION_ID` and stored in the `pane_sessions` table.
#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash)]
pub struct SessionId(Ulid);

impl SessionId {
    /// Creates a new id from the current time and a random component.
    #[must_use]
    pub fn new() -> Self {
        let mut generator = GENERATOR
            .get_or_init(|| Mutex::new(Generator::new()))
            .lock()
            .unwrap_or_else(PoisonError::into_inner);
        // The generator keeps ids monotonic inside the same millisecond; the
        // fallback only runs if the clock moved backwards, which is rare.
        Self(generator.generate().unwrap_or_else(|_| Ulid::generate()))
    }

    /// Wraps an existing ULID.
    #[must_use]
    pub const fn from_ulid(ulid: Ulid) -> Self {
        Self(ulid)
    }

    /// The underlying ULID.
    #[must_use]
    pub const fn as_ulid(&self) -> Ulid {
        self.0
    }

    /// The 26-character Crockford base32 form used on the wire.
    #[must_use]
    pub fn as_string(&self) -> String {
        self.0.to_string()
    }
}

static GENERATOR: OnceLock<Mutex<Generator>> = OnceLock::new();

impl Default for SessionId {
    fn default() -> Self {
        Self::new()
    }
}

impl fmt::Display for SessionId {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        self.0.fmt(formatter)
    }
}

impl FromStr for SessionId {
    type Err = ulid::DecodeError;

    fn from_str(value: &str) -> Result<Self, Self::Err> {
        Ulid::from_string(value).map(Self)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ids_round_trip_through_text() {
        let id = SessionId::new();
        let parsed: SessionId = id.to_string().parse().expect("valid ULID");
        assert_eq!(parsed, id);
        assert_eq!(parsed.as_string(), id.to_string());
    }

    #[test]
    fn ids_are_time_ordered() {
        let first = SessionId::new();
        let second = SessionId::new();
        assert!(first < second);
    }

    #[test]
    fn a_bad_id_is_rejected() {
        assert!("not-a-ulid".parse::<SessionId>().is_err());
    }
}
